INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1221192-che461', 'stk-user6441', 'CHE 461', 'info', '{"desc": "انا اخذت\n\nche461\n\npetroleum refining\n\nعند سليمان الخطاف\n\nالكورس حليو يعلمك كل شي يصير في الريفاينري من لحظة وصول الcrude oil من الرق للريفاينري الى البرودكتز \" قازولين, ديزل , الكينز , غاز الطبخ LGO ,…\"\n\nبتدرسوا كيف يكسرو “cracking” المركبات الكبيره الى اصغر عشان ينتجوا منه القازولين والديزل\nمثل الهايدروكراكينق , ثيرمال كراكينق, اتموسفيرك ديستيليشن, فاكيوم ديستيليشن , FCC\n\nوبعدين كيف تنظفوه من الميتال و السيلفر و الرصاص\nبالهايدرو تريتر , desalter\n\nوبرضه بتدرسو الاوكتين نمبرز \" octane numbers \" و الاشياء اللي تزيد قيمتهم\nباستخدام النفثا ريفورمر , الكيليشن , بوليمرايزيشن\n\nوبرضه الكاتاليزت المخصصه لكل بروسيس وكيف تزيدوا الانتاجيه بالعب بالرياكشن كونديشنز\n\nالكورس يبيله حفظ كثيير و قرايه ككثيير لان اكثر من نصف اسئلة الميد تيرم و الفاينل بتكون اختيارات واسئلة كونسبت\n\nاما اسئلة الكالكوليشن فهي طويييييله يبيلها وقت ولكن سيستماتيك\n, في الميجر يجيك سؤال او اثنين بس وعلها ساعة ونص او اكثر\n\nفي بروجيكت تسويه اخر السيميستر وعليه بريزينتيشن\n\nالدكتور سليمان الخطاف\n\nالدكتور ما يدرس كثير اصلا نادرا ما يدرس هو تبع ابحاث\nعشان كذا تشوف خبرته بالتدريس مو بذاك الزود وتعامله مع الطلاب مو كويس\nاسئلة المياجر من متوسط الى صعبة\nالكوزات تقريبا عطانا 9 كويزات و 8 هومووركات\nتصحيحه متوسط الى سيئ\nلالالالالالا ثم الف لا للتاخير عنده , لو تتاخر كل اللي في المبنى بيسمعوا تهزيئه لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/143746/10", "user": "user6441", "ts": 1368295636000, "tid": 143746, "pn": 10}}', 1368295636000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467544-che461', 'stk-najiali', 'CHE 461', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nأخذت كورسين إليكتف في التخصص وهم:\nCHE-461 Petroleum Refining\nCHE-432 Principle of Heat Exchanger Design\n\nالأول تم شرحه شرح كافي و وافي من طرف الأخ علبة البيبسي. الفرق هو الدكتور (أخذته مع الدكتور سمير الغامدي _ موظف في أرامكو_). الإضافة فقط عن الدكتور. دكتور سمير ذو أخلاق عالية جداً<مثل الدكتور باسم ❤️ ,ولا يهونوا باقي الدكاتره> ورجل يعمل بإخلاص في الشرح والمساعدة بكل الطرق الممكنة. طريقة الشرح تختلف من شخص الى آخر لكن أنا اعطيه B+ مقارنة بباقي الدكاتره في التخصص.\n\nبالنسبة لمادة المبادئ في تصميم المبادلات الحرارية\n\nأخذتها مع البروفيسور 🤴 رياض شوابكه. أستاذ رياض متمكن من المادة بشكل جنوني. طريقة الشرح مفصلة بشكل كبير جدا ويكتب كثير ع السبورة بالتفصيل. أي سؤال يمر في بالك يجاوبه لك اسرع من قوقل (ما شاء الله تبارك الله). المشكلة الوحيدة فيه انه شويات مزاجي ممكن يجيك مروق ويعطيك بروجكت ابو صفحة وحدة ويمكن يجيك ماله خلق ويعطيك هوم وورك يبالك سمستر كامل تحله. وأبشرك ماراح يمديك تخلصه 🚬. ببساطة إعتبرها مفاجأت الطريق.\n\nبالنسبة للكورس:\nأول بداية يتكلم عن النقل الحراري في الأنابيب وقوانين بسيطة كلها درسناها في 300. كذلك بعض الأمور البسيطة عن الfins و الكفاءة. بعدين يدخل في تصاميم المبادلات الحرارية بأنواعها المختلفة. بعدين يجيك طريقة ثانية في التصميم (هاي الطريقة متعلقة فقط في ال shell & tubes. من حيث تحسب كل شيء ممكن يؤثر ع حساب معامل الحرارة hi و ho. الطريقة الأولى اسمها KERNS METHOD و الثانية BELLS METHOD. طريقة بل فيها تفصيل كثير جدا وتحتاج تعرف اشياء كثيرة علشان تقدر تحل المسائل المتعلقة ب بل. بعدها يجيك تصميم ال condenser و ال re-boiler وكيف يؤثر الشكل في الحساب. وكيف يؤثر موقع ال condensate سواء داخل الأنابيب او خارجها. وغيرها الكثير. بعدها آخر شيء هو Heat Integration. كيف تقدر تستفيد من الحرارة اللي بالعادة ماتستخدم في حساباتنا. هذا القسم أشعر انه مفيد جداً لانه شيء جديد ومهم في تقليل الخسائر في العمليات داخل المصانع من حيث نزيد الكفاءة في إستخدام الطاقة. هذا بالمختصر عن الكورس من ناحية المحتوى. كورس ممتع وسهل وممكن تجيب درجة عالية فيه لأنه أغلب الحل يعتمد ع قوانين بطريقة منهجية. السئية الوحيد من وجهة نظري انه كورس يعتمد ع الحل بالتفصيل. وكذا يكون حل المسائل طويل وأي غلط بسيط في الحل ممكن يسبب مشكلة في إيجاد الغلط. في الإختبار النهائي كتبت ورقة للقوانين اللي أحتاجها وطلعت عندي 11 ورقة مكتوبة من الجهتين وبعضها مكتوبة بالكمبيوتر…!!!\n\nالكورس بالعموم أعطيه A+ من ناحية السهولة والمتعة والفائدة. مع العلم جبت فيه B+ 😄.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/143746/31", "user": "NajiAli", "ts": 1486158521000, "tid": 143746, "pn": 31}}', 1486158521000, 1794828443, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
